{
  "avaliacoes": [
    {
      "id": "E651fad1e0f693cda",
      "pertinente": true,
      "tipo": "explicacao_tecnica",
      "achados": [
        {
          "proposicao": "Unidades flutuantes de produção envelhecidas podem se aproximar do fim da vida de projeto e ainda permanecer economicamente atrativas devido à reavaliação da vida do reservatório ou ao aumento de recuperação viabilizado por novas tecnologias.",
          "trechos": [
            "E651fad1e0f693cda:0:694",
            "E651fad1e0f693cda:1390:2088"
          ],
          "condicoes": [
            "aplica-se a unidades flutuantes em águas profundas",
            "decorre de mudanças em condições de reservatório ou de adoção de tecnologias como gas lift, water injection ou water flooding"
          ],
          "limites": [
            "o texto caracteriza contexto e motivação econômica, não um critério suficiente para autorizar extensão de vida",
            "não apresenta método quantitativo de avaliação de vida remanescente"
          ]
        },
        {
          "proposicao": "A vida de projeto dessas instalações é finita e é condicionada por análise de fadiga baseada em condições ambientais específicas do local.",
          "trechos": [
            "E651fad1e0f693cda:694:1390"
          ],
          "condicoes": [
            "considera condições ambientais site-specific adotadas no projeto"
          ],
          "limites": [
            "não informa parâmetros, margens ou limites de fadiga",
            "não trata de outros mecanismos de dano além da fadiga nesse trecho"
          ]
        },
        {
          "proposicao": "Para continuidade além da vida de projeto, o texto indica a necessidade de um processo/metodologia de extensão de vida com avaliação abrangente da unidade, princípios de gestão da integridade e atividades de inspeção para verificar integridade estrutural e mecânica.",
          "trechos": [
            "E651fad1e0f693cda:694:1390",
            "E651fad1e0f693cda:1390:2088",
            "E651fad1e0f693cda:2088:2315"
          ],
          "condicoes": [
            "voltado à operação segura continuada além da vida de projeto",
            "deve apoiar mitigação de riscos e minimizar perda de produtividade"
          ],
          "limites": [
            "o texto descreve necessidade metodológica de forma geral",
            "não detalha critérios de aceitação, periodicidades de inspeção ou requisitos regulatórios brasileiros"
          ]
        }
      ]
    },
    {
      "id": "E2964a7c1d422d6c4",
      "pertinente": true,
      "tipo": "explicacao_tecnica",
      "achados": [
        {
          "proposicao": "A viabilidade e a extensão da continuidade operacional além da vida de projeto são afetadas por desafios operacionais e ambientais que incidem sobre a unidade ao longo do tempo.",
          "trechos": [
            "E2964a7c1d422d6c4:0:698",
            "E2964a7c1d422d6c4:698:1396"
          ],
          "condicoes": [
            "aplica-se a unidades flutuantes de produção projetadas para vida finita"
          ],
          "limites": [
            "o trecho não hierarquiza os desafios nem define método de decisão"
          ]
        },
        {
          "proposicao": "Exposição a ambiente mais severo que o previsto, atualização de dados meteoceanográficos e alterações na química da água ou na biologia marinha podem reduzir a adequação das premissas originais e agravar corrosão em casco e sistemas de ancoragem.",
          "trechos": [
            "E2964a7c1d422d6c4:698:1396"
          ],
          "condicoes": [
            "especialmente relevante em áreas sujeitas a furacões ou tufões",
            "depende de revisão das condições ambientais usadas no projeto"
          ],
          "limites": [
            "o texto cita corrosão química e biológica excessiva como achado, sem fornecer taxas, mecanismos detalhados ou limites admissíveis",
            "não afirma que esses fatores sempre inviabilizam a extensão de vida"
          ]
        },
        {
          "proposicao": "Como contrapeso aos desafios do envelhecimento, princípios de gestão da integridade de ativos, manutenção eficaz e regimes de inspeção podem apoiar a continuidade segura, desde que integrados a uma metodologia de extensão de vida robusta e flexível com avaliação completa da unidade.",
          "trechos": [
            "E2964a7c1d422d6c4:1396:2092"
          ],
          "condicoes": [
            "a continuidade segura requer preservação da integridade estrutural e mecânica desejada",
            "a metodologia precisa simultaneamente mitigar riscos e minimizar perda de produtividade"
          ],
          "limites": [
            "não especifica técnicas de inspeção, indicadores ou critérios de robustez",
            "permanece em nível conceitual"
          ]
        }
      ]
    },
    {
      "id": "Ebf1e4a20535a0476",
      "pertinente": true,
      "tipo": "explicacao_tecnica",
      "achados": [
        {
          "proposicao": "Para instalações envelhecidas, é importante conhecer claramente a condição real da unidade, assegurar a existência de um sistema eficaz de gestão de segurança e identificar investimentos necessários para operação segura no tempo de vida remanescente.",
          "trechos": [
            "Ebf1e4a20535a0476:0:696"
          ],
          "condicoes": [
            "aplica-se a instalações com vida estendida ou em discussão de extensão de vida"
          ],
          "limites": [
            "o trecho não define como medir a condição real nem como calcular os investimentos necessários"
          ]
        },
        {
          "proposicao": "O texto afirma haver interesse crescente em extensão de vida, mas pouco desenvolvimento público sobre o tema, especialmente para sistemas submarinos, e registra incerteza persistente apesar da necessidade de tratar o problema.",
          "trechos": [
            "Ebf1e4a20535a0476:696:1393"
          ],
          "condicoes": [
            "ênfase em sistemas submarinos associados"
          ],
          "limites": [
            "caracteriza lacuna de conhecimento público, não evidência de inviabilidade técnica",
            "números de tempo de operação e vida de projeto aparecem apagados e não podem ser reconstruídos"
          ]
        },
        {
          "proposicao": "Na análise internacional descrita, a autoridade norueguesa é apresentada como proativa na gestão de extensão de vida, com foco em padronização, guias, melhoria metodológica e capacitação, e um relatório citado aborda conceitos gerais de envelhecimento, riscos à integridade e formas de tratamento no processo de extensão de vida.",
          "trechos": [
            "Ebf1e4a20535a0476:1393:2093",
            "Ebf1e4a20535a0476:2093:2232"
          ],
          "condicoes": [
            "referido como comparação internacional",
            "relacionado a instalações offshore envelhecidas"
          ],
          "limites": [
            "trata-se de descrição de experiência estrangeira, não requisito brasileiro",
            "o trecho é resumido e não explicita critérios técnicos operacionais concretos"
          ]
        }
      ]
    },
    {
      "id": "E53665af769b5768b",
      "pertinente": true,
      "tipo": "recomendacao",
      "achados": [
        {
          "proposicao": "Na prática de gestão da segurança de processo, informações de segurança de processo devem ser fornecidas, mantidas e atualizadas para sustentar análise de riscos com dados concisos, seguros, atualizados e documentados.",
          "trechos": [
            "E53665af769b5768b:1391:2090"
          ],
          "condicoes": [
            "apresentado como elemento de uma prática de gestão da segurança de processo"
          ],
          "limites": [
            "o trecho não é específico de FPSO/FSO nem exclusivo de extensão de vida",
            "não define formatos documentais ou periodicidade de atualização"
          ]
        },
        {
          "proposicao": "A análise de riscos de processo é descrita como atividade permanente e estruturada em todas as etapas do ciclo de vida, podendo empregar técnicas como APR, What If-Checklist, FMEA, árvore de falhas e HAZOP.",
          "trechos": [
            "E53665af769b5768b:1391:2090",
            "E53665af769b5768b:2090:2730"
          ],
          "condicoes": [
            "abrange todas as etapas do ciclo de vida"
          ],
          "limites": [
            "o texto lista técnicas possíveis, sem selecionar qual usar para fadiga, corrosão ou vida remanescente",
            "não apresenta critérios de aceitação de risco"
          ]
        },
        {
          "proposicao": "Procedimentos operacionais e práticas seguras devem explicitar parâmetros de operação, limites de operação segura, sequências de parada normal e de emergência, consequências de operar fora desses limites e ações correspondentes; além disso, nenhuma mudança tecnológica deve ocorrer sem análise de riscos competente.",
          "trechos": [
            "E53665af769b5768b:2090:2730"
          ],
          "condicoes": [
            "aplicável à gestão operacional e ao gerenciamento de mudanças"
          ],
          "limites": [
            "o texto é genérico e não trata especificamente de inspeção especial, reparo estrutural ou avaliação de fitness-for-service",
            "não constitui norma identificada para FPSOs brasileiros"
          ]
        }
      ]
    },
    {
      "id": "E58a4b81ed1383d81",
      "pertinente": true,
      "tipo": "recomendacao",
      "achados": [
        {
          "proposicao": "Medidas associadas à extensão de vida podem incluir regime de inspeção reforçado, com aumento de frequência e/ou uso de técnicas diferentes, como migração de inspeção visual para ensaios não destrutivos, além de proteção anticorrosiva adicional ou reaplicação de revestimento.",
          "trechos": [
            "E58a4b81ed1383d81:0:698"
          ],
          "condicoes": [
            "dependem de áreas identificadas como necessitando dessas medidas",
            "a continuidade operacional segura é condicionada à implementação satisfatória dessas medidas e à obtenção de aprovações estatutárias"
          ],
          "limites": [
            "o trecho não define quando cada técnica deve ser adotada",
            "não informa intervalos de inspeção nem especificação de revestimentos"
          ]
        },
        {
          "proposicao": "O sucesso da metodologia de extensão de vida depende tanto do trabalho analítico e de projeto quanto da condição física da unidade.",
          "trechos": [
            "E58a4b81ed1383d81:0:698"
          ],
          "condicoes": [
            "voltado ao processo de extensão de vida de unidades flutuantes offshore envelhecidas"
          ],
          "limites": [
            "não há ponderação entre fatores analíticos e condição física"
          ]
        },
        {
          "proposicao": "Boas práticas apontadas no processo incluem manutenção de registros de projeto, inspeção, reparos e modificações; programa robusto de gestão da integridade de ativos; e uso dos registros da sociedade classificadora como linha de base de conformidade e condição de sistemas de segurança, estrutura e equipamentos mecânicos.",
          "trechos": [
            "E58a4b81ed1383d81:698:1391",
            "E58a4b81ed1383d81:1391:2091"
          ],
          "condicoes": [
            "aplica-se ao apoio da avaliação de integridade estrutural e mecânica na extensão de vida",
            "inclui interface da sociedade classificadora com agências estatutárias e regulatórias para alinhamento do processo"
          ],
          "limites": [
            "o texto apresenta boas práticas e papéis institucionais, não um requisito legal brasileiro",
            "não detalha conteúdo mínimo dos registros"
          ]
        }
      ]
    },
    {
      "id": "E8112ae5b2cabd595",
      "pertinente": true,
      "tipo": "norma",
      "achados": [
        {
          "proposicao": "O thorough review deve considerar mudanças nos parâmetros de projeto, envelhecimento da instalação e mudanças nas condições operacionais que possam influenciar a operação segura, para confirmar se o safety case continua adequado até a próxima revisão.",
          "trechos": [
            "E8112ae5b2cabd595:0:695"
          ],
          "condicoes": [
            "aplica-se ao processo de revisão aprofundada referido no documento do regulador offshore",
            "relacionado à adequação do safety case"
          ],
          "limites": [
            "refere-se ao contexto regulatório do Reino Unido",
            "não fornece método detalhado de avaliação de fadiga, corrosão ou obsolescência"
          ]
        },
        {
          "proposicao": "Para instalações que atingem o fim da vida de projeto original, deve ser realizada avaliação formal de extensão de vida para estabelecer a adequação à continuidade segura de operação.",
          "trechos": [
            "E8112ae5b2cabd595:695:1392"
          ],
          "condicoes": [
            "aplica-se a instalações no fim da vida de projeto original"
          ],
          "limites": [
            "o trecho não explicita escopo técnico mínimo da avaliação além dos pontos gerais subsequentes",
            "não deve ser convertido automaticamente em requisito brasileiro"
          ]
        },
        {
          "proposicao": "Essa avaliação formal deve demonstrar reavaliação de todos os riscos de acidentes maiores e que o nível de integridade da instalação seja mantido tão alto quanto razoavelmente praticável, podendo exigir submissão de mudança material ao safety case conforme o resultado.",
          "trechos": [
            "E8112ae5b2cabd595:695:1392"
          ],
          "condicoes": [
            "relacionado a riscos para pessoas na instalação decorrentes de questões de integridade",
            "a necessidade de mudança material depende do resultado das avaliações"
          ],
          "limites": [
            "conceito ALARP/HARP é do contexto regulatório citado e não equivale, por si só, a obrigação normativa brasileira",
            "o trecho não estabelece critérios quantitativos de demonstração"
          ]
        }
      ]
    }
  ],
